import base64, sys, urllib.parse

raw = ""

decoded = base64.b64decode(raw).decode("utf-8")
print("DECODED:", decoded[:200])
parsed = urllib.parse.parse_qs(decoded)
code = parsed.get("code", [""])[0]
state = parsed.get("state", [""])[0]
print("CODE:", code[:80], "...")
print("STATE:", state)
print("EXPECTED_STATE:", "b4d653b1-60a9-4640-ba0b-b19590e897e6")
print("MATCH:", state == "b4d653b1-60a9-4640-ba0b-b19590e897e6")
